    Bug 2039652 - Back out changeset dab18c5a3df2 (bug 2031264) for breaking the calendar UI. r=vineet

    This broke the UI by causing a race condition with the code that loads the calendar list in calendar-management.js.

    Differential Revision: https://phabricator.services.mozilla.com/D300605

diff --git a/calendar/base/src/CalCachedCalendar.sys.mjs b/calendar/base/src/CalCachedCalendar.sys.mjs
index cad07682044..bd981584ea8 100644
--- a/calendar/base/src/CalCachedCalendar.sys.mjs
+++ b/calendar/base/src/CalCachedCalendar.sys.mjs
@@ -97,11 +97,7 @@ calCachedCalendarObserverHelper.prototype = {

   onPropertyChanged(aCalendar, aName, aValue, aOldValue) {
     if (!this.isCachedObserver) {
-      const home = this.home;
-      // Avoid reentrancy.
-      Services.tm.dispatchToMainThread(() => {
-        home.mObservers.notify("onPropertyChanged", [home, aName, aValue, aOldValue]);
-      });
+      this.home.mObservers.notify("onPropertyChanged", [this.home, aName, aValue, aOldValue]);
     }
   },
